import { parse } from "@std/jsonc";

// Keep the generated config beside the source so relative paths and the lockfile resolve identically.
const config = parse(await Deno.readTextFile("deno.jsonc"));
if (config === null || typeof config !== "object" || Array.isArray(config)) {
    throw new Error("deno.jsonc must contain a JSON object");
}

await Deno.writeTextFile(
    "deno.node-modules.jsonc",
    "// Generated from deno.jsonc by deno task config:node-modules. Do not edit.\n" +
        JSON.stringify({ ...config, nodeModulesDir: "auto", jsrDepsInNodeModules: true }, null, 4) + "\n",
);
